import{c as t,Q as o,j as r,m as a}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"Samsung Tizen TV App","description":"","frontmatter":{},"headers":[],"relativePath":"clients/tizen.md","filePath":"clients/tizen.md"}'),n={name:"clients/tizen.md"};function i(s,e,l,h,d,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="samsung-tizen-tv-app" tabindex="-1">Samsung Tizen TV App <a class="header-anchor" href="#samsung-tizen-tv-app" aria-label="Permalink to &quot;Samsung Tizen TV App&quot;">​</a></h1><p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.13 <strong>Since:</strong> 0.18.0</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The Phlix app for Samsung Smart TVs runs on 2018 and newer Samsung TVs powered by Tizen. Enable Developer Mode on your TV, sideload the <code>.wgt</code> package from a USB drive, then open the app and enter your server URL or sign in with your Hub account.</p></div><h2 id="install-store-links" tabindex="-1">Install / Store Links <a class="header-anchor" href="#install-store-links" aria-label="Permalink to &quot;Install / Store Links&quot;">​</a></h2><ul><li><strong>Samsung Galaxy Store:</strong> <a href="#">Phlix on Galaxy Store</a></li><li><strong>Direct <code>.wgt</code> download:</strong> <a href="https://github.com/detain/phlix-tizen-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-tizen-client/releases</a> — for sideloading</li></ul><h2 id="platform-specific-install-steps" tabindex="-1">Platform-Specific Install Steps <a class="header-anchor" href="#platform-specific-install-steps" aria-label="Permalink to &quot;Platform-Specific Install Steps&quot;">​</a></h2><h3 id="step-1-—-enable-developer-mode-on-the-tv" tabindex="-1">Step 1 — Enable Developer Mode on the TV <a class="header-anchor" href="#step-1-—-enable-developer-mode-on-the-tv" aria-label="Permalink to &quot;Step 1 — Enable Developer Mode on the TV&quot;">​</a></h3><ol><li>Power on your Samsung TV and open <strong>Settings</strong>.</li><li>Navigate to <strong>About → Support → Developer Mode</strong>.</li><li>Set <strong>Developer Mode</strong> to <strong>On</strong>.</li><li>The TV will prompt you to restart. Confirm and wait for the TV to reboot.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Developer Mode must remain <strong>On</strong> for sideloaded apps to run. Turning it off will remove all sideloaded applications.</p></div><h3 id="step-2-—-sideload-the-wgt-file" tabindex="-1">Step 2 — Sideload the <code>.wgt</code> File <a class="header-anchor" href="#step-2-—-sideload-the-wgt-file" aria-label="Permalink to &quot;Step 2 — Sideload the `.wgt` File&quot;">​</a></h3><ol><li>Download the latest <code>.wgt</code> file from <a href="https://github.com/detain/phlix-tizen-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-tizen-client/releases</a> to a computer.</li><li>Format a USB drive as <strong>FAT32</strong>.</li><li>Copy the <code>.wgt</code> file to the root of the USB drive.</li><li>On the TV, open <strong>My Apps</strong> from the home screen.</li><li>Insert the USB drive into the TV&#39;s USB port.</li><li>Open the TV&#39;s <strong>File Manager</strong> app → <strong>USB</strong> → click the <code>.wgt</code> file.</li><li>Confirm the installation. The Phlix app icon appears in <strong>My Apps</strong>.</li></ol><h3 id="step-3-—-network-requirement" tabindex="-1">Step 3 — Network Requirement <a class="header-anchor" href="#step-3-—-network-requirement" aria-label="Permalink to &quot;Step 3 — Network Requirement&quot;">​</a></h3><p>The TV must be on the same local network as your Phlix server, or connected via the Hub relay for remote access. Avoid connecting the TV to a &quot;guest&quot; network that isolates devices from each other.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="in-app-server-url" tabindex="-1">In-App Server URL <a class="header-anchor" href="#in-app-server-url" aria-label="Permalink to &quot;In-App Server URL&quot;">​</a></h3><ol><li>Open <strong>Phlix</strong> from <strong>My Apps</strong>.</li><li>On first launch, enter your server&#39;s address: <ul><li><strong>Local:</strong> <code>http://192.168.1.100:32400</code> (replace with your server&#39;s LAN IP)</li><li><strong>Hub relay:</strong> <code>https://hub.phlix.example.com</code> (after signing in with Hub)</li></ul></li><li>The URL is saved automatically. Update it in <strong>Settings → Server URL</strong> later.</li></ol><h3 id="environment-variable-for-packaged-builds" tabindex="-1">Environment Variable (for Packaged Builds) <a class="header-anchor" href="#environment-variable-for-packaged-builds" aria-label="Permalink to &quot;Environment Variable (for Packaged Builds)&quot;">​</a></h3><p>For automated or kiosk-style deployments, you can embed the server URL at build time by setting <code>window.PHLIX_SERVER_URL</code> in the build configuration. See the <a href="https://github.com/detain/phlix-tizen-client/blob/master/README.md" target="_blank" rel="noreferrer">Tizen client readme</a> for details.</p><h2 id="hub-connection" tabindex="-1">Hub Connection <a class="header-anchor" href="#hub-connection" aria-label="Permalink to &quot;Hub Connection&quot;">​</a></h2><ol><li>In the Phlix app, open <strong>Settings</strong> (gear icon).</li><li>Navigate to <strong>Hub → Sign In</strong>.</li><li>Enter the Hub URL (e.g., <code>https://hub.phlix.example.com</code>) and press <strong>OK</strong> on your remote.</li><li>Enter your Hub username and password using the on-screen keyboard.</li><li>After authentication, the server is auto-selected from your Hub account. No manual server URL entry is needed.</li></ol><p>Hub login means your TV app works anywhere — the Hub relay handles the connection when you are away from home.</p><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="developer-mode-not-enabled" tabindex="-1">Developer Mode not enabled <a class="header-anchor" href="#developer-mode-not-enabled" aria-label="Permalink to &quot;Developer Mode not enabled&quot;">​</a></h3><p><strong>Symptom:</strong> When trying to install the <code>.wgt</code> file, the TV shows &quot;Installation blocked&quot; or the File Manager does not respond to the <code>.wgt</code> file.</p><p><strong>Fix:</strong> Return to <strong>Settings → About → Support → Developer Mode</strong> and ensure it is set to <strong>On</strong>. After toggling, restart the TV for the change to take effect. Re-insert the USB and try again.</p><h3 id="wrong-tv-model-year-tizen-version" tabindex="-1">Wrong TV model year / Tizen version <a class="header-anchor" href="#wrong-tv-model-year-tizen-version" aria-label="Permalink to &quot;Wrong TV model year / Tizen version&quot;">​</a></h3><p><strong>Symptom:</strong> During installation, the TV shows &quot;This app is not compatible with this TV&quot; or the installation silently fails.</p><p><strong>Fix:</strong> Confirm your TV model year is <strong>2018 or newer</strong>. Phlix requires Tizen 4.0 or later. Update your TV&#39;s firmware in <strong>Settings → Support → Software Update</strong>. If your TV is older, use the web client (<code>http://your-server:32400/web</code>) in the TV&#39;s browser instead.</p><h3 id="network-isolation-preventing-server-access" tabindex="-1">Network isolation preventing server access <a class="header-anchor" href="#network-isolation-preventing-server-access" aria-label="Permalink to &quot;Network isolation preventing server access&quot;">​</a></h3><p><strong>Symptom:</strong> The app opens but displays &quot;Server unreachable&quot; immediately after entering the server URL.</p><p><strong>Fix:</strong> Verify the TV and your Phlix server are on the <strong>same subnet</strong>. Some Samsung TVs have network isolation features that prevent devices on one network from seeing each other. Ensure both devices are on the same LAN. Try using the server&#39;s direct LAN IP instead of a hostname. If you are traveling, use the Hub relay URL after signing in with Hub.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./roku.html">Roku</a> — alternative living room streaming platform</li><li><a href="./windows.html">Windows client</a> — desktop app with system tray and media key support</li><li><a href="./../advanced/live-tv.html">Live TV</a> — watch live television through the Phlix app</li></ul>',33)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
